<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $money=static fn($v)=>'R$ '.number_format((float)$v,2,',','.'); ?>
<section class="promotion-list"><div class="admin-page-head"><h2>Promoções e cupons</h2><a class="admin-button admin-button-primary" href="/admin/promotion/create">+ Nova promoção</a></div>
<form method="get" action="/admin/promotion/index" class="admin-filters">
<select name="is_active"><option value="">Ativas e inativas</option><option value="1" <?= $is_active === '1' ? 'selected' : '' ?>>Só ativas</option><option value="0" <?= $is_active === '0' ? 'selected' : '' ?>>Só inativas</option></select>
<input type="search" name="q" placeholder="Nome ou website" value="<?= $e($q) ?>">
<?= \Iter\Admin\View\Sort::hidden() ?>
<button type="submit">Filtrar</button>
</form>
<table><thead><tr><?= \Iter\Admin\View\Sort::th('name', 'Promoção', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('application', 'Aplicação', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('discount', 'Desconto', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('websites', 'Websites', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('starts', 'Validade', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('is_active', 'Status', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('coupons', 'Cupons', $sort, $dir) ?><?= \Iter\Admin\View\Sort::th('uses', 'Usos', $sort, $dir) ?><th></th></tr></thead><tbody>
<?php if (!$promotions): ?><tr><td colspan="9" class="admin-empty">Nenhuma promoção cadastrada.</td></tr><?php endif; ?>
<?php foreach($promotions as $p): ?><tr><td><?= $e($p['name']) ?><br><small>Prioridade <?= (int)$p['priority'] ?><?= $p['is_accumulative']?' · acumulativa':'' ?></small></td><td><?= $p['application_type']==='automatic'?'Automática':'Por cupom' ?></td><td><?= $p['discount_type']==='percent'?$e($p['discount_amount']).'%':$money($p['discount_amount']) ?></td><td><?= $e($p['websites']) ?></td><td><?= $e($p['starts_at'] ?: '—') ?> até <?= $e($p['ends_at'] ?: '—') ?></td><td><span class="admin-status admin-status-<?= $p['is_active'] ? 'on' : 'off' ?>"><?= $p['is_active'] ? 'Ativa' : 'Inativa' ?></span></td><td><?= (int)$p['coupon_count'] ?></td><td><?php if (\Iter\Admin\Auth::isAllowed('Iter_Promotion::usages')): ?><a href="/admin/promotion/uses?id=<?= (int)$p['promotion_id'] ?>"><?= (int)$p['redemption_count'] ?></a><?php else: ?><?= (int)$p['redemption_count'] ?><?php endif; ?></td><td class="admin-row-action"><a href="/admin/promotion/edit?id=<?= (int)$p['promotion_id'] ?>">Editar</a> <form method="post" action="/admin/promotion/delete" data-confirm="Remover esta promoção?"><?= \Iter\Core\FormKey::field() ?><input type="hidden" name="promotion_id" value="<?= (int)$p['promotion_id'] ?>"><button type="submit">Remover</button></form></td></tr><?php endforeach; ?>
</tbody></table>
<?php \Iter\Admin\View\Pager::render($pager); ?>
</section>
